        for(j=0;j<C;j++)printf(" %d",a[i][j]);
        printf("\n");
    }
    for(i=0;i<R;i++)
        for(j=0;j<C;j++){
            if(a[mr][mc]<a[i][j]){mr=i;mc=j;}
            if(a[nr][nc]>a[i][j]){nr=i;nc=j;}
        }
    int t=a[mr][mc];a[mr][mc]=a[nr][nc];a[nr][nc]=t;
    printf("交换后:\n");
    for(i=0;i<R;i++){
        for(j=0;j<C;j++)printf(" %d",a[i][j]);
        printf("\n");
    }
}

